use std::{collections::HashSet,fs::File,io::{BufRead,BufReader}};
use serde_json::Value;
pub fn recorded_kernel_tool_names(path:&str)->Vec<String>{let Ok(f)=File::open(path)else{return vec![]};let mut out=HashSet::new();for line in BufReader::new(f).lines().map_while(Result::ok){let Ok(v)=serde_json::from_str::<Value>(&line)else{continue};let Some(m)=v.get("message")else{continue};if m.get("role").and_then(Value::as_str)!=Some("toolResult"){continue}let tn=m.get("toolName").and_then(Value::as_str);for p in m.get("content").and_then(Value::as_array).into_iter().flatten(){if p.get("type").and_then(Value::as_str)==Some("text")&&let Some(t)=p.get("text").and_then(Value::as_str)&&let Ok(x)=serde_json::from_str::<Value>(t)&&let Some(n)=x.get("kernel_tool").and_then(Value::as_str)&&(tn.is_none()||tn==Some(n)){out.insert(n.to_string());}}}out.into_iter().collect()}
